insert into woerter (slug, wort, artikel, ipa, wortart, kategorie, definition, bedeutungen, beispiel) values
  ('liawa-vueue-rost-aun-da-kraxn-ois-schbinnweem-aun-da-muffn', 'Liawa vüü Rost aun da Kraxn ois Schbinnweem aun da Muffn!', '', '', '', 'Sex, Erotik und Bettgeflüster auf Wienerisch', 'Lieber viel Rost an der Kraxen als Spinnweben an der Muffe!', '[{"kategorie": "wörtlich", "text": "\"Lieber viel Rost an der Karre als Spinnweben an der Muschi!\"  2. Lieber ''ne durchgerittene Mühle als ''ne eingerostete Jungfrau!  3. Besser ein warmgefahrenes Modell als eins mit Spinnweben unterm Sitz!"}]'::jsonb, ''),
  ('dea-hod-so-schiss-kriagd-dem-hods-de-muffn-zuazoong', 'Dea hod so Schiss kriagd, dem hods de Muffn zuazoong!', '', '', '', 'Wiener Gaunersprache', 'Der hat so Schiss gekriegt, dem hat’s die Muffe zugezogen!', '[{"kategorie": "wörtlich", "text": "\"Der hatte so viel Schiss, dass es ihm das Arschloch zugezogen hat!\"  2. Der hatte solche Angst,  dass ihm der Arsch auf Grundeis ging! 3. Dem ist derart der [[Reis]] gegangen, dass es ihm die Rosette zugedreht hat wie ''nen Wasserhahn!"}]'::jsonb, ''),
  ('wia-noch-da-gebuat-auf-amoi-a-schwoaza-mual-im-wicklpoista-gleeng-is-hod-ia-famuelie-ned-schlechd-gschaud', 'Wia noch da Gebuat auf amoi a schwoaza Mual im Wicklpoista gleeng is, hod ia Famülie ned schlechd gschaud!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Als nach der Geburt auf einmal ein schwarzer Murl im Wickelpolster gelegen ist, hat ihre Familie nicht schlecht geschaut!', '[{"kategorie": "wörtlich", "text": "\"Als nach der Geburt plötzlich ein schwarzer Mohr im Wickelpolster gelegen ist, hat ihre Familie nicht schlecht geschaut!\"  2. Als plötzlich ein dunkles Köpfchen aus dem Wickelkörbchen lachte, brachte das die festgefügten Familienbilder kurz ins Wanken!  3. Die Familie hat große Augen gemacht, als ihnen aus dem Wickelpolster plötzlich ein dunkelhäutiges Baby entgegenlachte!"}]'::jsonb, ''),
  ('da-oide-hengst-woara-echta-mual-tiafschwoaz-vom-maeaenanaunsotz-bis-zum-schwaafschbitz', 'Da oide Hengst woara echta Mual - tiafschwoaz vom Määnanaunsotz bis zum Schwaafschbitz!', '', '', '', 'Viecher und Tiernamen auf Wienerisch', 'Der alte Hengst war ein echter Mohr – tiefschwarz vom Mähnenansatz bis zur Schweifspitze!', '[{"kategorie": "wörtlich", "text": "\"Der alte Hengst war pechschwarz wie ein Mohr – von der Mähne bis zur Schweifspitze!\"  2. Von der Stirn bis zum Schweif war der alte Hengst schwarz wie die Nacht!  3. Er war tiefschwarz gefärbt, der alte Hengst – glänzend von der Mähne bis zum letzten Haar am Schweif!"}]'::jsonb, ''),
  ('gib-ma-no-an-mual-owa-desmoi-mid-uandlich-schmoiz', 'Gib ma no an Mual - owa desmoi mid uandlich Schmoiz!', '', '', '', 'Trinken, Saufen & Tschechern auf Wienerisch', 'Gib mir noch einen Murl - aber diesmal mit ordentlich Schmalz!', '[{"kategorie": "wörtlich", "text": "\"Gib mir noch einen Kaffee mit Jägermeister - aber diesmal mit ordentlich Schmalz!\"  2. Gib mir noch einen Jägerkaffee - aber diesmal hau g''scheit rein!  3. Gib mir noch einen schwarzen Kaffee mit Jägermunition - aber diesmal schieß richtig rein!"}]'::jsonb, ''),
  ('laut-wia-de-pummarin', 'laut wia de Pummarin', '', '', '', 'Religiöses & Göttliches auf Wienerisch', 'laut wie die Pummerin', '[{"kategorie": "wörtlich", "text": "\"laut dröhnend wie der Klang der Pummerin\""}, {"kategorie": "", "text": "\"krachend laut wie die Pummerin zu Neujahr\""}, {"kategorie": "", "text": "\"laut wie der Donnerschlag der Pummerin\""}]'::jsonb, ''),
  ('de-schdimm-vom-pfoarra-is-lauta-ois-de-pummarin-droeoend-bis-ind-letzte-eckn-von-da-kiachn', 'De Schdimm vom Pfoarra is lauta ois de Pummarin - dröönd bis ind letzte Eckn von da Kiachn!', '', '', '', 'Religiöses & Göttliches auf Wienerisch', 'Die Stimme des Pfarrers ist lauter als die Pummerin - dröhnt bis in die letzte Ecke der Kirche!', '[{"kategorie": "wörtlich", "text": "\"Die Stimme des Pfarrers hat mehr Wucht als die Pummerin – sie rüttelt sogar die Kirchgänger in den letzten Reihen auf!\"  2. Wenn unser Pfarrer predigt, klingt es, als würde die Pummerin durch''s Kirchenschiff rollen!  3. Unser Pfarrer braucht kein Mikro – der hat die Pummerin in den Stimmbändern!"}]'::jsonb, ''),
  ('de-pummarin-is-aane-von-de-greessdn-freischwingendn-kiachnglochn-in-europa', 'De Pummarin is aane von de greessdn freischwingendn Kiachnglochn in Europa!', '', '', '', 'Wiener Wörter mit schillernder Geschichte', 'Die Pummerin ist eine der größten freischwingenden Kirchenglocken in Europa!', '[{"kategorie": "wörtlich", "text": "\"Die Pummerin zählt zu den größten freischwingenden Kirchenglocken in ganz Europa!\"  2. Mit über 20 Tonnen Gewicht gehört die Pummerin zu Europas größten freischwingenden Kirchenglocken!  3. Die ehrwürdige Pummerin im Nordturm des Wiener Stephansdoms ist nicht nur riesig, sondern auch eine der wenigen freischwingenden Großglocken Europas!"}]'::jsonb, ''),
  ('haedasd-eam-gscheid-noochtarockiad-warad-da-schdich-seina-gweesn', 'Hädasd eam gscheid noochtarockiad, warad da Schdich seina gweesn!', '', '', '', 'Wiener Kartentipplerjargon', 'Hättest du ihm g''scheit nachtarockiert, wäre der Stich seiner gewesen!', '[{"kategorie": "wörtlich, Kartenspielerjargon", "text": "\"Wenn du ihm ihm ordentlich nachtarockiert hättest, hätt er jetzt den Stich gemacht!\"  2. Ein Stich wäre drin gewesen, hättest du g’scheit nachtarockiert!  3. Hättest du ihm Tarock nachgelegt, wär der Stich seiner gewesen!"}]'::jsonb, ''),
  ('kennt-ma-ned-amoi-wos-guad-sei-lossn-oone-dass-glei-wiida-wea-noochtarockiad', 'Kennt ma ned amoi wos guad sei lossn, oone dass glei wiida wea noochtarockiad?', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Könnten wir nicht einmal etwas gut sein lassen, ohne dass gleich wieder wer nachtarockiert?', '[{"kategorie": "wörtlich", "text": "\"Könnten wir’s nicht einmal gut sein lassen, ohne dass gleich wieder jemand nachhakt?\"  2. Könnten wir nicht mal was durchgehen lassen, ohne dass gleich wieder einer nachstichelt?  3. Könnten wir’s nicht einfach dabei belassen, ohne dass gleich wieder einer den Erbsenzähler gibt?"}]'::jsonb, ''),
  ('nooch-den-laungan-haatschara-hauma-uns-mid-an-aafochn-nochtmoi-begnueuegd-nua-brood-kaas-und-butta', 'Nooch den laungan Haatschara hauma uns mid an aafochn Nochtmoi begnüügd - nua Brood, Kaas und Butta!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Nach dem langen Hatscherer haben wir uns mit einem einfachen Nachtmahl begnügt - nur Brot, Käse und Butter!', '[{"kategorie": "wörtlich", "text": "\"Nach dem langen Fußmarsch haben wir uns mit einem einfachen Abendbrot zufriedengegeben - nur Brot, Käse und Butter!\"  2. Nach der langen Wanderung gab es zur Stärkung nur ein einfaches Abendmahl: Brot, Käse und Butter!  3. Nach der langen Wanderung haben wir uns eine schnelle Abendjause gemacht – nur Brot, Käse und Butter!"}]'::jsonb, ''),
  ('loss-uns-bei-keaznschein-schee-nochdmoin-und-daunn-zu-weit-ins-bettal-foin', 'Loss uns bei Keaznschein schee nochdmoin und daunn zu weit ins Bettal foin!', '', '', '', 'Sex, Erotik und Bettgeflüster auf Wienerisch', 'Lass uns bei Kerzenschein schön nachtmahlen und dann zu zweit ins Bettchen fallen!', '[{"kategorie": "wörtlich", "text": "\"Erst das Nachtmahl bei Kerzenglanz, dann im Schlafgemach der süße Tanz!\"  2. Erst dinieren bei Kerzenschein, dann im Bette Träume teil''n!  3. Erst das Mahl im sanften Glanze, dann der Reigen im Matratzen-Tanze!"}]'::jsonb, ''),
  ('liawa-a-volla-nochtscheabm-ois-a-leara-goeoedbeidl', 'Liawa a volla Nochtscheabm ois a leara Göödbeidl!', '', '', '', 'Wiener Gefühlsäußerungen & Kult-Sager', 'Lieber ein voller Nachtscherben als ein leerer Geldbeutel!', '[{"kategorie": "wörtlich", "text": "\"Lieber ein voller Nachttopf als ein leerer Geldbeutel!\"  2. Lieber ein volles Töpfchen als ein leeres Täschchen!  3. Besser der Nachttopf läuft über, als dass der Geldbeutel austrocknet!"}]'::jsonb, ''),
  ('auf-mein-nochtkastl-schdapaen-si-de-biadoosn-do-is-ka-plotz-mea-fias-beetbiachl', 'Auf mein Nochtkastl schdapän si de Biadoosn - do is ka Plotz mea fias Beetbiachl!', '', '', '', 'Trinken, Saufen & Tschechern auf Wienerisch', 'Auf meinem Nachtkastl stapeln sich die Bierdosen – da ist kein Platz mehr fürs Betbüchl!', '[{"kategorie": "wörtlich", "text": "\"Auf meinem Nachttisch stapeln sich die Bierdosen – da ist kein Platz mehr fürs Gebetbuch!\"  2. Mein Nachttisch ist ein Bierfriedhof – da hat kein Heiligenbild mehr Platz!  3. Auf meinem Betttischchen türmen sich die Bierdosen – da ist kein Platz mehr für die Bibel!"}]'::jsonb, ''),
  ('waunna-si-in-nochzipf-in-mathe-ned-ausbessad-bleibda-sitzn', 'Waunna si in Nochzipf in Mathe ned ausbessad, bleibda sitzn!', '', '', '', 'Wiener Jugendsprache & Teenie-Talk', 'Wenn er sich den Nachzipf in Mathematik nicht ausbessert, bleibt er sitzen!', '[{"kategorie": "wörtlich", "text": "\"Wenn er die Nachprüfung in Mathematik nicht besteht, muss er die Klasse wiederholen!\"  2. Schafft er die Wiederholungsprüfung in Mathematik nicht, darf er das Schuljahr noch einmal genießen!  3. Wenn er den Nachzipf nicht wegkriegt, heißt’s: Klasse wiederholen!"}]'::jsonb, ''),
  ('dea-blaeaede-schmaeae-zipfd-ma-bis-heit-no-nooch', 'Dea blääde Schmää zipfd ma bis heit no nooch!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Dieser blöde Schmäh zipft mir bis heute noch nach!', '[{"kategorie": "wörtlich", "text": "\"Dieser blöde Scherz hängt mir bis heute noch nach!\"  2. Diesen blöden Scherz hält man mir bis heute noch vor!  3. Dieser blöde Schmäh verfolgt mich bis heute noch wie ein Schatten"}]'::jsonb, ''),
  ('in-da-lobau-san-lauta-nockabatzln-untawegs-und-des-ned-nua-im-fkk-gelaende', 'In da Lobau san lauta Nockabatzln untawegs - und des ned nua im FKK-Gelände!', '', '', '', 'Sex, Erotik und Bettgeflüster auf Wienerisch', 'In der Lobau sind lauter Nackerpatzeln unterwegs - und das nicht nur im FKK-Gelände!', '[{"kategorie": "wörtlich", "text": "\"In der Lobau sind jede Menge Nackedeis unterwegs – und das nicht nur am FKK-Strand!\"  2. In der Lobau stolperst du dauernd über Nackte – auch dort, wo sie nichts verloren haben!  3. In der Lobau laufen so viele nackte Gestalten herum, man glaubt fast, man ist in einem Freiluft-Saunaclub!"}]'::jsonb, ''),
  ('a-geistigs-nockabatzl', 'a geistigs Nockabatzl', '', '', '', 'Wiener Sprüche, die sitzen!', 'ein geistiges Nackerpatzel', '[{"kategorie": "wörtlich", "text": "\"ein geistig Nackter\""}, {"kategorie": "scherzhaft für", "text": "eine geistige Null, \"ein geistiges Leichtgewicht\", \"ein geistiger Tiefflieger\", ein geistiges [[Armutschkerl]]"}]'::jsonb, 'So a geistigs Nockabatzl wia den do kaunnsd ned amoi de Kaffeemaschin eischoitn lossn!'),
  ('so-a-geistigs-nockabatzl-wia-den-do-kaunnsd-ned-amoi-de-kaffeemaschin-eischoitn-lossn', 'So a geistigs Nockabatzl wia den do kaunnsd ned amoi de Kaffeemaschin eischoitn lossn!', '', '', '', 'Wiener Gefühlsäußerungen & Kult-Sager', 'So ein geistiges Nackerpatzel wie den da kannst du nicht einmal die Kaffemaschine einschalten lassen!', '[{"kategorie": "wörtlich", "text": "\"So einen geistigen Blindgänger wie den da kannst du nicht einmal die Kaffemaschine einschalten lassen!\"  2. So ein geistiger Tiefflieger wie der da bringt’s nicht mal fertig, bei der Kaffeemaschine auf den richtigen Knopf zu drücken!  3. So ein geistiges Armutschkerl wie der da ist schon überfordert, wenn er die Kaffeemaschine einschalten soll!"}]'::jsonb, 'a geistigs Nockabatzl'),
  ('i-woa-total-nockad-wiara-ma-de-ollas-entscheidende-pruefungsfroog-gschdoeoed-hod', 'I woa total nockad, wiara ma de ollas entscheidende Prüfungsfroog gschdööd hod!', '', '', '', 'Wiener Jugendsprache & Teenie-Talk', 'Ich war total nackert, wie er mir die alles entscheidende Prüfungsfrage gestellt hat!', '[{"kategorie": "wörtlich", "text": "\"Ich war völlig blank, als er mir die alles entscheidende Prüfungsfrage stellte!\"  2. Nackt wie auf dem Klo stand ich vor ihm, als er mir die alles entscheidende Prüfungsfrage stellte!  3. Just bei der Entscheidungsfrage war bei mir Ebbe – Hirn leer, Hosen runter!"}]'::jsonb, ''),
  ('joe-schau-so-a-sau-joessasna-wos-mochd-a-nockada-im-hawelka', 'Jö schau, so a Sau, jössasna! Wos mochd a Nockada im Hawelka?', '', '', '', 'Wienerisches aus Musik, Kunst, Kultur & Medien', 'Jö, schau, so ''ne Sau, Jesus nein! Was macht ein Nackerter im Hawelka?', '[{"kategorie": "wörtlich, Refrainzeile aus Georg Danzers legendärem Song ''Jö schau, so a Sau!''", "text": "\"Oh schau, so ''ne Sau, um Himmels willen! Da kommt ein Nackerter ins Café Hawelka!\"  2. Na sowas, schau, da sitzt ein nacktes Mannsbild im Café Hawelka!  3. Mensch, guck, da sitzt ein Splitternackter mitten im Café Hawelka!"}]'::jsonb, ''),
  ('dea-noogld-ollas-wos-zwa-fiass-hod', 'Dea noogld ollas, wos zwa Fiass hod!', '', '', '', 'Sex, Erotik und Bettgeflüster auf Wienerisch', 'Der nagelt alles, was zwei Füße hat!', '[{"kategorie": "wörtlich", "text": "\"Der vögelt alles, was zwei Beine hat!\"  2. Der knallt alles, was halbwegs geradeaus gehen kann!  3. Der schustert alles, was nicht niet- und nagelfest ist!"}]'::jsonb, ''),
  ('i-hob-de-kraxn-bis-zum-auschlog-gnoogld-da-mual-hod-brueued-wiara-sau', 'I hob de Kraxn bis zum Auschlog gnoogld - da Mual hod brüüd wiara Sau!', '', '', '', 'Wiener Mechaniker-Slang', 'Ich hab die Kraxen bis zum Anschlag genagelt – der Murl hat gebrüllt wie''ne  Sau!', '[{"kategorie": "wörtlich", "text": "\"Ich hab die Karre bis zum Anschlag genagelt – der Motor hat aufgeheult wie ''ne wie Sau!\"  2. Ich hab die Blechkiste bis zum Anschlag hochgeprügelt – der Motor hat gekreischt wie irre!  3. Ich hab den Schlitten bis in den Begrenzer genagelt, Alter – das Ding hat gebrüllt wie Sau!"}]'::jsonb, ''),
  ('i-noogl-da-an-jeedn-boin-aus-30-maeaeta-millimaeaetagenau-ins-kreizeck', 'I noogl da an jeedn Boin aus 30 Määta millimäätagenau ins Kreizeck!', '', '', '', 'Wiener Fußballer- und Sportlerjargon', 'Ich nagle dir jeden Ball aus 30 Meter millimetergenau ins Kreuzeck!', '[{"kategorie": "wörtlich", "text": "\"Ich pfeffer dir jeden Ball aus 30 Metern millimetergenau in den Giebel!\"  2. Ich baller dir das Leder aus jeder Entfernung genau in den Knick, Bruder!  3. Ich setz dir das Ding aus 30 Metern oben rein wie nix, Alter!"}]'::jsonb, ''),
  ('ka-wunda-dass-den-kaana-moog-dea-frisst-jo-sein-eiganan-noosnraummae', 'Ka Wunda, dass den kaana moog - dea frisst jo sein eiganan Noosnraummä!', '', '', '', 'Wiener Gefühlsäußerungen & Kult-Sager', 'Kein Wunder, dass den keiner mag - der frisst ja seinen eigenen Nasenrammel!', '[{"kategorie": "wörtlich", "text": "\"Kein Wunder, dass den keiner mag - der mampft ja seinen eigenen Nasenrotz!\"  2. Kein Wunder, dass den keiner leiden kann – der fischt dauernd den Rotz aus der Nase und futtert ihn dan auch noch!  3. Kein Wunder, dass der unbeliebt ist – der verspeist ja seinen eigenen Popel!"}]'::jsonb, ''),
  ('dea-is-a-neafal-vuam-hean-hypaventiliad-schoo-waunns-haendy-nua-no-5-akku-hod', 'Dea is a Neafal vuam Hean - hypaventiliad schoo, waunns Händy nua no 5% Akku hod!', '', '', '', 'Wiener Gefühlsäußerungen & Kult-Sager', 'Der is ein Nerverl vor dem Herrn – hyperventiliert schon, wenn das Handy nur noch 5% Akku hat!', '[{"kategorie": "wörtlich", "text": "Der ist ein wandelndes Nervenbündel – der zittert schon, wenn das Handy nur noch 5% Akku hat!  2. Dem steht die Dauerpanik ins Gesicht geschrieben – kriegt schon die Krise, wenn das Handy nur noch 5% Akku hat!  3. So einen Hysteriker wie den hab ich ja noch nie gesehen – bei 5% Akku kriegt der schon Todesangst!"}]'::jsonb, ''),
  ('neafal-ned-asoo', 'Neafal ned asoo!', '', '', '', '', 'Nerverl doch nicht so!', '[{"kategorie": "wörtlich", "text": "\"Werd nicht gleich so nervös!\"  2. Zappel nicht so nervös herum!  3. Hör auf zu nerven, bitte!"}]'::jsonb, ''),
  ('hea-auf-mi-weng-an-jeedn-schaas-z-neafaln', 'Hea auf, mi weng an jeedn Schaas z''neafaln!', '', '', '', '', 'Hör auf, mich wegen jedem Schas zu nerverln!', '[{"kategorie": "wörtlich", "text": "\"Hör auf, mich wegen jeder Kleinigkeit zu nerven!\"  2. Hör auf, mich wegen jedem Furz zu belästigen!  3. Hör auf, mich wegen jedem Schmarren zu behelligen!"}]'::jsonb, ''),
  ('tua-ned-umanaundneafaln-wiara-aufgscheichds-hendl', 'Tua ned umanaundneafaln wiara aufgscheichds Hendl!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Tu nicht herumnerverln wie ein aufgescheuchtes Hendl!', '[{"kategorie": "wörtlich", "text": "\"Nerv nicht rum wie ein aufgescheuchtes Huhn!\"  2. Zappel nicht rum wie ein Hamster im Laufrad!  3. Flatter nicht rum wie eine Motte im Lampenschirm!"}]'::jsonb, ''),
  ('da-nowak-sei', 'da Nowak sei', '', '', '', 'Wiener Sprüche, die sitzen!', 'der Nowak sein', '[{"kategorie": "fig., scherzhaft für", "text": "\"der Arsch vom Dienst\" sein, der Dumme sein, der Prügelknabe sein (gutmütige Person, die ständig ausgenützt wird)"}]'::jsonb, ''),
  ('aana-is-imma-da-nowak', 'Aana is imma da Nowak!', '', '', '', 'Wiener Gefühlsäußerungen & Kult-Sager', 'Einer ist immer der Nowak!', '[{"kategorie": "wörtlich", "text": "\"Einer ist immer der Dumme!\"  2. \"Einer ist immer ''der Arsch vom Dienst''!\""}, {"kategorie": "", "text": "\"Einer ist immer der Blöde, an dem alles hängen bleibt!\""}]'::jsonb, 'da Nowak sei'),
  ('da-schaeaef-hod-gsoogd-aana-muass-do-sei-na-dreimoi-deafst-roodn-wear-in-nowaktoog-ausgfossd-hod', 'Da Schääf hod gsoogd: ''Aana muass do sei!'' - na dreimoi deafst roodn, wear in Nowaktoog ausgfossd hod!', '', '', '', 'Handwerk und Beruf – so sagt''s der Wiener!', 'Der Chef hat gesagt: ''Einer muss da sein'' – na dreimal darfst du raten, wer den Nowak-Tag ausgefasst hat!', '[{"kategorie": "wörtlich", "text": "\"Der Chef hat gesagt: ''Einer muss da sein'' – na dreimal darfst du raten, wer am Fenstertag in der Firma sein darf!\"  2. Wenn''s heißt: ‚Einer muss da sein‘, kannst drauf wetten – der Nowak-Tag gehört mir!  3. Der Chef sagt: ‚Einer muss arbeiten‘ – logisch, dass ich wieder mal ich den Nowak-Tag kassiere!"}]'::jsonb, ''),
  ('an-echtn-oestarreicha-eakennsd-daran-dassa-de-fenstatoog-schoo-im-jaenna-vaplant', 'An echtn Östarreicha eakennsd daran, dassa de Fenstatoog schoo im Jänna vaplant!', '', '', '', 'Wiener Gefühlsäußerungen & Kult-Sager', 'Einen echten Österreicher erkennst du daran, dass er die Fenstertage schon im Jänner verplant!', '[{"kategorie": "wörtlich", "text": "\"Ein echten Österreicher erkennt man dran, dass er Fenstertage schon im Jänner plant!\"  2. Ein echter Österreicher hat die Fenstertage schon im Kalender markiert, bevor der Jänner überhaupt noch angefangen hat!  3. Wenn in Österreich was fix ist, dann dass die Fenstertage im Jänner schon unter Verschluss sind!"}]'::jsonb, ''),
  ('zwickltoog-des-is-da-toog-aun-dem-de-gscheidn-ualaub-haum-und-de-trottln-im-buero-hockn', 'Zwickltoog? Des is da Toog, aun dem de Gscheidn Ualaub haum und de Trottln im Büro hockn!', '', '', '', 'Wiener Gefühlsäußerungen & Kult-Sager', 'Zwickeltag? Das ist der Tag, an dem die G’scheiten Urlaub haben und die Trotteln im Büro hocken!', '[{"kategorie": "wörtlich", "text": "\"\"Zwickeltag? Das ist der Tag, an dem die Intelligenten Urlaub haben und die Deppen im Büro sitzen!\"  2. \"Zwickeltag? Das ist der Tag, an dem die Klugen verlängertes Wochenende machen und die Dummen Dienst schieben!\"  3. \"Zwickeltag? Das ist der wahre Intelligenztest der Nation: Wer plant, liegt im Liegestuhl. Wer nicht, hockt im Großraumbüro!\""}]'::jsonb, ''),
  ('wea-neega-zu-eam-sogd-riskiad-a-flak', 'Wea Neega zu eam sogd, riskiad a Flak!', '', '', '', 'Wiener Gaunersprache', 'Wer ''Neger'' zu ihm sagt, riskiert ''ne Flak!', '[{"kategorie": "wörtlich", "text": "\"Wer ''Neger'' zu ihm sagt, riskiert eine donnernde Ohrfeige!\"  2. Wer ihn mit ‚Neger‘ anspricht, kriegt eine geknallt!  3. Wer ihn ‚Neger‘ nennt, dem fliegt gleich eine mordstrumm Watschen um die Ohren!"}]'::jsonb, ''),
  ('neega-sei', 'neega sei', '', '', '', 'Wiener Sprüche, die sitzen!', 'neger sein', '[{"kategorie": "wörtlich", "text": "\"völlig mittellos sein\" (eigtl. \"schwarz [abgebrannt] sein\", im Gegensatz zu \"hochweiß\" [vermögend] sein)"}, {"kategorie": "allg.", "text": "pleite sein, bankrott sein, [[tippelflach]] sein"}]'::jsonb, ''),
